source('/home/jinshengxi/bladder_metabolism/results/llps_C5_cellchat_visualization_v3/scripts/common.R');STAGE<-'03_network_figures.R';startstage()
ns<-r('tables/network_summary_t20.csv');z<-annotate_dir(copy(ns[(sender==C5|receiver==C5)&sender!=receiver]));pn<-r('tables/patient_network_t20.csv');mx<-max(z$patient_condition_median,na.rm=TRUE)
for(full in c(FALSE,TRUE)){
 nodes<-data.table(node=if(full)c(C5,setdiff(G,C5))else c(C5,TME));nodes[,angle:=pi/2+2*pi*(seq_len(.N)-1)/.N];nodes[,`:=`(x=cos(angle),y=sin(angle))]
 for(dir in c('outgoing','incoming',if(!full)'bidirectional')){
  e<-copy(z[partner%in%nodes$node]);if(dir!='bidirectional')e<-e[direction==dir];e[,`:=`(x=nodes$x[match(sender,nodes$node)],y=nodes$y[match(sender,nodes$node)],xe=nodes$x[match(receiver,nodes$node)],ye=nodes$y[match(receiver,nodes$node)])];e[,`:=`(xs=x+.035*(xe-x),ys=y+.035*(ye-y),xt=xe-.035*(xe-x),yt=ye-.035*(ye-y))]
  p<-ggplot()+geom_curve(data=e[!is.na(patient_condition_median)&patient_condition_median>0],aes(xs,ys,xend=xt,yend=yt,linewidth=patient_condition_median,color=direction),curvature=.2,arrow=grid::arrow(length=grid::unit(.1,'inches'),type='closed'))+scale_color_manual(values=c(outgoing='#AD6D34',incoming='#4C7098'),limits=c('outgoing','incoming'),drop=FALSE,name='Direction')+scale_linewidth_continuous(limits=c(0,mx),range=c(.4,2.4),name='Patient median strength')+geom_point(data=nodes,aes(x,y,fill=node),shape=21,size=5,color='black',show.legend=FALSE)+scale_fill_manual(values=cols)+geom_text(data=nodes,aes(x*1.12,y*1.15,label=nice(node),hjust=ifelse(x>.1,0,ifelse(x<-.1,1,.5))),family='Arial',size=4)+coord_equal(xlim=c(-1.7,1.7),ylim=c(-1.4,1.4),clip='off')+jin_theme()+theme(axis.text=element_blank(),axis.line=element_blank(),axis.ticks=element_blank())+labs(x=NULL,y=NULL)
  expfig(p,'01_circle_plot',paste0(if(full)'full14_'else'C5_TME_',dir),e,11,8,role=if(full)'Supplementary figures'else'Main figure candidates',purpose='C5 directed network; no self-self',limitation='Same layout and linewidth scale across all circles; edge-specific denominators in CSV; unplotted NA differs from zero')
 }
}
# Bidirectional triangles, same numerical scale. Gray NA, no self-self.
triangles<-function(fibs,name){
 a<-ns[sender%in%fibs&receiver%in%TME,.(fibro=sender,partner=receiver,direction='outgoing',strength=patient_condition_median,n=eligible_patients)];b<-ns[receiver%in%fibs&sender%in%TME,.(fibro=receiver,partner=sender,direction='incoming',strength=patient_condition_median,n=eligible_patients)];d<-rbind(a,b);d[,`:=`(xx=match(partner,TME),yy=length(fibs)+1-match(fibro,fibs))];pol<-rbindlist(lapply(seq_len(nrow(d)),function(i){v<-d[i];if(v$direction=='outgoing'){dx<-c(-.48,.48,-.48);dy<-c(.48,.48,-.48)}else{dx<-c(-.48,.48,.48);dy<-c(-.48,-.48,.48)};v<-v[rep(1,3)];v[,`:=`(x=xx+dx,y=yy+dy,id=i)];v}));lim<-c(0,max(pol$strength,na.rm=TRUE));la<-d[,.(x=xx+ifelse(direction=='outgoing',-.17,.17),y=yy+ifelse(direction=='outgoing',.2,-.2),strength,n)]
 for(labels in c(FALSE,TRUE)){p<-ggplot(pol,aes(x,y,group=id,fill=strength))+geom_polygon(color='white',linewidth=.4)+scale_fill_viridis_c(limits=lim,na.value='grey80',guide=cb(),name='Patient median strength')+scale_x_continuous(breaks=seq_along(TME),labels=nice(TME))+scale_y_continuous(breaks=seq_along(fibs),labels=nice(rev(fibs)))+jin_theme()+theme(axis.text.x=element_text(angle=35,hjust=1),axis.line=element_blank(),axis.ticks=element_blank())+labs(x=NULL,y=NULL)
 if(C5%in%fibs)p<-p+annotate('rect',xmin=.5,xmax=7.5,ymin=length(fibs)+1-match(C5,fibs)-.5,ymax=length(fibs)+1-match(C5,fibs)+.5,fill=NA,color='black',linewidth=.6)
 if(labels)p<-p+geom_text(data=la,aes(x,y,label=ifelse(is.na(strength),'NA',formatC(strength,format='g',digits=2)),color=ifelse(is.na(strength)|strength>.5*lim[2],'black','white')),inherit.aes=FALSE,size=3,family='Arial')+scale_color_identity()
 expfig(p,'02_dual_triangle_heatmap',paste0(name,if(labels)'_numbers'else'_plain'),pol,11,if(length(fibs)==1)3.5 else 8,purpose='Upper-left fibro to TME; lower-right TME to fibro',limitation='Actual medians, no row scaling; C5 row outlined; denominators differ')}
 dd<-d[direction=='outgoing'];p<-heat(dd,'partner','fibro','n',TME,fibs,label=TRUE,fillname='Eligible independent patients')+scale_x_discrete(labels=nice(TME))+scale_y_discrete(labels=nice(rev(fibs)));expfig(p,'02_dual_triangle_heatmap',paste0(name,'_eligible_patients'),dd,10,if(length(fibs)==1)3.3 else 7,role='Supplementary figures',purpose='Eligibility counts, identical for the two directions')
}
triangles(FIB,'fibro_TME');triangles(C5,'C5_TME')
for(metric in c('strength','count')){d<-if(metric=='strength')copy(ns)else r('tables/network_count_t20.csv');val<-if(metric=='strength')'patient_condition_median'else'median_count';d[sender==receiver,(val):=NA_real_];d[,self_excluded:=sender==receiver];p<-heat(d,'receiver','sender',val,G,G,fillname=paste('Patient median',metric))+scale_x_discrete(labels=nice(G))+scale_y_discrete(labels=nice(rev(G)));expfig(p,'02_dual_triangle_heatmap',paste0('full14_interaction_',metric),d,11,9,role='Supplementary figures',purpose='Full14 directed network; diagonal intentionally omitted',limitation='Gray diagonal is self excluded; other gray cells are ineligible')}
zz<-z[partner%in%TME];for(dir in c('outgoing','incoming','bidirectional')){d<-if(dir=='bidirectional')copy(zz)else zz[direction==dir];ord<-d[,.(v=max(patient_condition_median)),by=partner][order(-v),partner];d[,partner_plot:=factor(partner,levels=ord)];p<-ggplot(d,aes(partner_plot,patient_condition_median,fill=direction))+geom_col(position=position_dodge(.8),width=.75)+geom_text(aes(label=paste0('n=',eligible_patients)),position=position_dodge(.8),vjust=-.5,size=3.5,family='Arial')+scale_fill_manual(values=c(outgoing='#AD6D34',incoming='#4C7098'),name='Direction')+scale_x_discrete(labels=nice)+scale_y_continuous(expand=expansion(mult=c(0,.15)))+jin_theme()+labs(x=NULL,y='Patient median communication strength')+theme(axis.text.x=element_text(angle=35,hjust=1));expfig(p,'03_communication_strength',paste0('C5_strength_',dir),d,10,5.5,purpose='Sorted actual strengths and eligible patients')}
d<-copy(zz);d[,label:=paste0(nice(partner),' (n=',eligible_patients,')')];p<-ggplot(d,aes(patient_condition_median,label,color=direction))+geom_errorbar(aes(xmin=patient_condition_q25,xmax=patient_condition_q75),orientation='y',position=position_dodge(.5),width=.2,linewidth=.4)+geom_point(position=position_dodge(.5),size=2.5)+scale_color_manual(values=c(outgoing='#AD6D34',incoming='#4C7098'),name='Direction')+jin_theme()+labs(x='Patient communication strength (median and IQR)',y=NULL);expfig(p,'03_communication_strength','C5_strength_IQR_forest',d,10,6,purpose='Patient median and interquartile range',limitation='IQR is spread, not confidence interval; no inferential P values')
for(part in TME[1:4])for(dir in c('outgoing','incoming')){d<-if(dir=='outgoing')pn[sender==C5&receiver==part&eligible==TRUE]else pn[sender==part&receiver==C5&eligible==TRUE];p<-ggplot(d,aes(dataset,weight,color=dataset))+geom_boxplot(outlier.shape=NA,linewidth=.4,width=.45)+geom_point(position=position_jitter(width=.12,seed=123),size=2)+scale_color_manual(values=jin_palette(unique(d$dataset)),name='Dataset')+jin_theme()+labs(x=NULL,y='Patient communication strength')+theme(axis.text.x=element_text(angle=25,hjust=1));expfig(p,'03_communication_strength',paste0(part,'_',dir,'_patient_distribution'),d,7,5,purpose='Patient heterogeneity by dataset')}
c<-r('tables/fibro_common_patient_pairs.csv');cs<-r('tables/fibro_common_summary.csv');for(o in setdiff(FIB,C5)){d<-cs[other==o&partner%in%TME[1:4]];d[,label:=paste0(nice(partner),' (n=',n_patients,')')];p<-ggplot(d,aes(median_difference,label,color=direction))+geom_vline(xintercept=0,linetype='dashed',linewidth=.4)+geom_errorbar(aes(xmin=q25,xmax=q75),orientation='y',width=.2,position=position_dodge(.5),linewidth=.4)+geom_point(position=position_dodge(.5))+jin_theme()+labs(x=paste('C5 -',nice(o),'paired difference (median and IQR)'),y=NULL,color='Direction');expfig(p,'03_communication_strength',paste0('C5_vs_',nice(o),'_common_IQR'),d,10,5,role='Supplementary figures',purpose='Matched specimen then patient comparison',limitation='Exploratory small matched subset; no hypothesis test; IQR is not CI')}
for(part in TME[1:4])for(dir in c('outgoing','incoming')){d<-c[other=='Fibro_C0'&partner==part&direction==dir];d<-melt(d,id.vars=c('patient_id','dataset','clinical_group','partner','direction'),measure.vars=c('other_strength','C5'),variable.name='subgroup',value.name='strength');d[,subgroup:=factor(subgroup,levels=c('other_strength','C5'),labels=c('C0','C5'))];p<-ggplot(d,aes(subgroup,strength,group=patient_id,color=dataset))+geom_line(linewidth=.4)+geom_point(size=2)+jin_theme()+labs(x=NULL,y='Communication strength',color='Dataset');expfig(p,'03_communication_strength',paste0('C5_vs_C0_',part,'_',dir,'_paired'),d,6.5,5,role='Supplementary figures',purpose='Matched patients only',limitation='Small common-specimen subset, not representative of all eligible C5 patients')}
cat('NETWORK FIGURES COMPLETE\n')
